import React, { useEffect, useState } from 'react';
import axios from 'axios';

const API_URL = 'http://localhost:3000';

interface Machine {
  id: number;
  name: string;
  status: string;
  production: number;
  temperature: number;
}

interface Alert {
  id: number;
  machine: string;
  type: string;
  message: string;
}

function LandingPage({ onEnter }: { onEnter: () => void }) {
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    setTimeout(() => setVisible(true), 100);
  }, []);

  return (
    <div style={{
      minHeight: '100vh',
      background: '#000913',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      fontFamily: 'Inter, sans-serif',
      position: 'relative',
      overflow: 'hidden',
    }}>

      {/* Grade de fundo */}
      <div style={{
        position: 'absolute', inset: 0,
        backgroundImage: 'linear-gradient(rgba(0,200,255,0.03) 1px, transparent 1px), linear-gradient(90deg, rgba(0,200,255,0.03) 1px, transparent 1px)',
        backgroundSize: '50px 50px',
      }} />

      {/* Círculo brilhante */}
      <div style={{
        position: 'absolute',
        width: '600px', height: '600px',
        background: 'radial-gradient(circle, rgba(0,150,255,0.08) 0%, transparent 70%)',
        borderRadius: '50%',
        top: '50%', left: '50%',
        transform: 'translate(-50%, -50%)',
      }} />

      {/* Conteúdo */}
      <div style={{
        textAlign: 'center', zIndex: 1,
        opacity: visible ? 1 : 0,
        transform: visible ? 'translateY(0)' : 'translateY(30px)',
        transition: 'all 1s ease',
      }}>

        {/* Badge */}
        <div style={{
          display: 'inline-block',
          background: 'rgba(0,150,255,0.1)',
          border: '1px solid rgba(0,150,255,0.3)',
          borderRadius: '20px',
          padding: '6px 16px',
          fontSize: '12px',
          color: '#00aaff',
          letterSpacing: '2px',
          textTransform: 'uppercase',
          marginBottom: '24px',
        }}>
          Indústria 4.0 · Monitoramento em Tempo Real
        </div>

        {/* Título */}
        <h1 style={{
          fontSize: '64px',
          fontWeight: '800',
          margin: '0 0 8px',
          background: 'linear-gradient(135deg, #ffffff 0%, #00aaff 100%)',
          WebkitBackgroundClip: 'text',
          WebkitTextFillColor: 'transparent',
          lineHeight: 1.1,
        }}>
          SmartFactory
        </h1>
        <h2 style={{
          fontSize: '64px',
          fontWeight: '800',
          margin: '0 0 24px',
          background: 'linear-gradient(135deg, #00aaff 0%, #0055ff 100%)',
          WebkitBackgroundClip: 'text',
          WebkitTextFillColor: 'transparent',
          lineHeight: 1.1,
        }}>
          Dashboard
        </h2>

        <p style={{
          color: '#64748b',
          fontSize: '18px',
          maxWidth: '500px',
          lineHeight: 1.6,
          margin: '0 auto 48px',
        }}>
          Sistema de monitoramento industrial com dados em tempo real, alertas inteligentes e análise de produção.
        </p>

        {/* Botão */}
        <button onClick={onEnter} style={{
          background: 'linear-gradient(135deg, #0055ff, #00aaff)',
          border: 'none',
          borderRadius: '50px',
          padding: '16px 48px',
          fontSize: '16px',
          fontWeight: '700',
          color: '#fff',
          cursor: 'pointer',
          letterSpacing: '1px',
          boxShadow: '0 0 30px rgba(0,150,255,0.4)',
          transition: 'all 0.3s ease',
        }}
          onMouseOver={e => (e.currentTarget.style.transform = 'scale(1.05)')}
          onMouseOut={e => (e.currentTarget.style.transform = 'scale(1)')}
        >
          ACESSAR SISTEMA →
        </button>

        {/* Stats */}
        <div style={{
          display: 'flex', gap: '48px',
          justifyContent: 'center',
          marginTop: '64px',
        }}>
          {[
            { value: '5', label: 'Máquinas' },
            { value: '99%', label: 'Uptime' },
            { value: 'Real', label: 'Tempo Real' },
          ].map((s, i) => (
            <div key={i} style={{ textAlign: 'center' }}>
              <p style={{ fontSize: '28px', fontWeight: '700', color: '#00aaff', margin: '0 0 4px' }}>{s.value}</p>
              <p style={{ fontSize: '12px', color: '#475569', margin: 0, letterSpacing: '1px', textTransform: 'uppercase' }}>{s.label}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function Dashboard() {
  const [machines, setMachines] = useState<Machine[]>([]);
  const [alerts, setAlerts] = useState<Alert[]>([]);

  useEffect(() => {
    axios.get(`${API_URL}/api/machines`).then(res => setMachines(res.data));
    axios.get(`${API_URL}/api/alerts`).then(res => setAlerts(res.data));
  }, []);

  const operando = machines.filter(m => m.status === 'operando').length;
  const falha = machines.filter(m => m.status === 'falha').length;
  const manutencao = machines.filter(m => m.status === 'manutenção').length;
  const mediaProducao = machines.length > 0
    ? Math.round(machines.reduce((a, m) => a + m.production, 0) / machines.length)
    : 0;

  const statusColor = (status: string) => {
    if (status === 'operando') return '#00ff88';
    if (status === 'falha') return '#ff3355';
    return '#ffaa00';
  };

  return (
    <div style={{ minHeight: '100vh', background: '#000913', color: '#e2e8f0', fontFamily: 'Inter, sans-serif', padding: '24px', backgroundImage: 'linear-gradient(rgba(0,200,255,0.02) 1px, transparent 1px), linear-gradient(90deg, rgba(0,200,255,0.02) 1px, transparent 1px)', backgroundSize: '50px 50px' }}>

      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '32px', borderBottom: '1px solid rgba(0,150,255,0.2)', paddingBottom: '16px' }}>
        <div>
          <h1 style={{ fontSize: '22px', fontWeight: '700', color: '#00aaff', margin: '0 0 4px' }}>⚙️ SmartFactory Dashboard</h1>
          <p style={{ color: '#475569', margin: 0, fontSize: '13px' }}>Monitoramento Industrial em Tempo Real</p>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <div style={{ width: '8px', height: '8px', borderRadius: '50%', background: '#00ff88', boxShadow: '0 0 8px #00ff88' }} />
          <span style={{ color: '#00ff88', fontSize: '12px' }}>SISTEMA ONLINE</span>
        </div>
      </div>

      {/* Cards */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '16px', marginBottom: '24px' }}>
        {[
          { label: 'Operando', value: operando, color: '#00ff88' },
          { label: 'Em Falha', value: falha, color: '#ff3355' },
          { label: 'Manutenção', value: manutencao, color: '#ffaa00' },
          { label: 'Produção Média', value: `${mediaProducao}%`, color: '#00aaff' },
        ].map((card, i) => (
          <div key={i} style={{ background: 'rgba(0,150,255,0.05)', border: '1px solid rgba(0,150,255,0.15)', borderRadius: '12px', padding: '20px', position: 'relative', overflow: 'hidden' }}>
            <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: '2px', background: `linear-gradient(90deg, transparent, ${card.color}, transparent)` }} />
            <p style={{ color: '#475569', fontSize: '12px', margin: '0 0 8px', textTransform: 'uppercase', letterSpacing: '1px' }}>{card.label}</p>
            <p style={{ fontSize: '36px', fontWeight: '800', color: card.color, margin: 0, textShadow: `0 0 20px ${card.color}44` }}>{card.value}</p>
          </div>
        ))}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', marginBottom: '20px' }}>

        {/* Máquinas */}
        <div style={{ background: 'rgba(0,150,255,0.05)', border: '1px solid rgba(0,150,255,0.15)', borderRadius: '12px', padding: '20px' }}>
          <h2 style={{ fontSize: '14px', fontWeight: '600', margin: '0 0 16px', color: '#00aaff', textTransform: 'uppercase', letterSpacing: '1px' }}>🏭 Máquinas</h2>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {machines.map(m => (
              <div key={m.id} style={{ background: 'rgba(0,0,0,0.3)', border: `1px solid ${statusColor(m.status)}22`, borderRadius: '8px', padding: '12px 16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <p style={{ margin: '0 0 4px', fontWeight: '600', fontSize: '13px', color: '#e2e8f0' }}>{m.name}</p>
                  <p style={{ margin: 0, fontSize: '11px', color: '#475569' }}>🌡️ {m.temperature}°C &nbsp;|&nbsp; 📦 {m.production}%</p>
                </div>
                <span style={{ background: `${statusColor(m.status)}15`, color: statusColor(m.status), fontSize: '10px', fontWeight: '700', padding: '4px 10px', borderRadius: '20px', border: `1px solid ${statusColor(m.status)}44`, textTransform: 'uppercase', letterSpacing: '1px', textShadow: `0 0 8px ${statusColor(m.status)}` }}>
                  {m.status}
                </span>
              </div>
            ))}
          </div>
        </div>

        {/* Produção */}
        <div style={{ background: 'rgba(0,150,255,0.05)', border: '1px solid rgba(0,150,255,0.15)', borderRadius: '12px', padding: '20px' }}>
          <h2 style={{ fontSize: '14px', fontWeight: '600', margin: '0 0 16px', color: '#00aaff', textTransform: 'uppercase', letterSpacing: '1px' }}>📊 Produção por Máquina</h2>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            {machines.map(m => (
              <div key={m.id}>
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px', color: '#64748b', marginBottom: '6px' }}>
                  <span>{m.name}</span>
                  <span style={{ color: statusColor(m.status), fontWeight: '700' }}>{m.production}%</span>
                </div>
                <div style={{ height: '6px', background: 'rgba(255,255,255,0.05)', borderRadius: '3px' }}>
                  <div style={{ width: `${m.production}%`, height: '100%', background: `linear-gradient(90deg, ${statusColor(m.status)}88, ${statusColor(m.status)})`, borderRadius: '3px', boxShadow: `0 0 8px ${statusColor(m.status)}66`, transition: 'width 0.8s ease' }} />
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Alertas */}
      <div style={{ background: 'rgba(0,150,255,0.05)', border: '1px solid rgba(0,150,255,0.15)', borderRadius: '12px', padding: '20px' }}>
        <h2 style={{ fontSize: '14px', fontWeight: '600', margin: '0 0 16px', color: '#00aaff', textTransform: 'uppercase', letterSpacing: '1px' }}>🚨 Alertas Recentes</h2>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {alerts.map(a => (
            <div key={a.id} style={{ background: a.type === 'critico' ? 'rgba(255,51,85,0.08)' : a.type === 'aviso' ? 'rgba(255,170,0,0.08)' : 'rgba(255,255,255,0.03)', border: `1px solid ${a.type === 'critico' ? 'rgba(255,51,85,0.25)' : a.type === 'aviso' ? 'rgba(255,170,0,0.25)' : 'rgba(255,255,255,0.08)'}`, borderRadius: '8px', padding: '12px 16px', display: 'flex', gap: '12px', alignItems: 'center' }}>
              <div style={{ width: '8px', height: '8px', borderRadius: '50%', background: a.type === 'critico' ? '#ff3355' : a.type === 'aviso' ? '#ffaa00' : '#475569', boxShadow: a.type === 'critico' ? '0 0 8px #ff3355' : a.type === 'aviso' ? '0 0 8px #ffaa00' : 'none', flexShrink: 0 }} />
              <div>
                <p style={{ margin: '0 0 2px', fontWeight: '600', fontSize: '13px', color: a.type === 'critico' ? '#ff3355' : a.type === 'aviso' ? '#ffaa00' : '#64748b' }}>{a.machine}</p>
                <p style={{ margin: 0, fontSize: '12px', color: '#475569' }}>{a.message}</p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default function App() {
  const [page, setPage] = useState<'landing' | 'dashboard'>('landing');
  return page === 'landing' ? <LandingPage onEnter={() => setPage('dashboard')} /> : <Dashboard />;
}
